package com.example.Hospital.Management.System.services; import com.example.Hospital.Management.System.entities.*; import com.example.Hospital.Management.System.dtos.*; import com.example.Hospital.Management.System.repositories.*; import com.example.Hospital.Management.System.exceptions.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class StaffService{private final StaffRepository r;private final DepartmentRepository dr;public StaffService(StaffRepository r,DepartmentRepository dr){this.r=r;this.dr=dr;} private Staff find(Long id){return r.findById(id).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Staff not found"));} private StaffDTO dto(Staff e){return StaffDTO.builder().id(e.getId()).name(e.getName()).role(e.getRole()).phoneNumber(e.getPhoneNumber()).departmentId(e.getDepartment().getId()).build();} private void apply(Staff e,StaffDTO d){Department dep=dr.findById(d.getDepartmentId()).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Department not found"));e.setName(d.getName());e.setRole(d.getRole());e.setPhoneNumber(d.getPhoneNumber());e.setDepartment(dep);} public StaffDTO create(StaffDTO d){Staff e=new Staff();apply(e,d);return dto(r.save(e));} public List<StaffDTO> all(){return r.findByIsActiveTrue().stream().map(this::dto).toList();} public StaffDTO get(Long id){return dto(find(id));} public StaffDTO update(Long id,StaffDTO d){Staff e=find(id);apply(e,d);return dto(r.save(e));} public void delete(Long id){Staff e=find(id);e.setIsActive(false);r.save(e);}}
